import type { ComponentProps, ElementType, ReactNode } from "react";

import { IconArrowRight } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";
import { CategoryNav } from "@rhs-ui/marketing/faq-sidebar-categories/category-nav";
import { CopyLinkButton } from "@rhs-ui/marketing/faq-sidebar-categories/copy-link-button";

export interface FaqQuestion {
  /** Stable and URL-safe: it is the anchor (#id) that support replies and search results link to. */
  id: string;
  question: string;
  /** The answer in full: text, or paragraphs and links. It is always in the page. */
  answer: ReactNode;
}

export interface FaqCategory {
  /** Stable and URL-safe: the category can be linked as #id. */
  id: string;
  title: string;
  questions: readonly FaqQuestion[];
}

export interface FaqContact {
  /** "Still have a question?". */
  title: string;
  description?: string;
  /** The button's text: "Talk to support". */
  label: string;
  href: string;
}

export interface FaqLabels {
  /** The category list's landmark name. */
  categories: string;
  /** Read after each count: "questions". */
  questions: string;
  /** The permalink button's accessible name. */
  copyLink: string;
  /** Said in words after the link was copied. */
  linkCopied: string;
  /** Said when the browser refused to copy. */
  copyFailed: string;
}

export interface FaqSidebarCategoriesProps extends Omit<ComponentProps<"section">, "title"> {
  /** A small line above the title: "Help centre". */
  eyebrow?: string;
  title: string;
  /** The title's element: "h2" (the default) inside a page, "h1" when the FAQ is the page. Categories go one level below it, questions one more. */
  titleAs?: "h1" | "h2";
  description?: string;
  categories: readonly FaqCategory[];
  /** A closing block for readers whose question is not here. */
  contact?: FaqContact;
  /** Called after a permalink was copied, with the question id and the full address. Works inside a Client Component. */
  onCopyLink?: (id: string, url: string) => void;
  /** Renders the contact link. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** Replaces any of the fixed words, for another language. */
  labels?: Partial<FaqLabels>;
}

const LABELS: FaqLabels = {
  categories: "Categories",
  questions: "questions",
  copyLink: "Copy link to this answer",
  linkCopied: "Link copied",
  copyFailed: "Copy it from the address bar",
};

const LEVELS = {
  h1: { category: "h2", question: "h3" },
  h2: { category: "h3", question: "h4" },
} as const;

/**
 * A long FAQ on one URL: a sticky list of categories with question counts
 * beside every question and answer, all open. Each question is a heading with
 * a permalink button that updates the hash and confirms in words, and the ids
 * are stable, so links from support replies keep working and the targeted
 * answer is highlighted on arrival. The current category follows the scroll
 * and carries aria-current; below lg the list becomes a scrolling row under
 * the title. Unlike FaqTabs, every answer stays in the DOM, which is what
 * search engines and support teams link to. Set `--sticky-top` (for example
 * `className="[--sticky-top:4rem]"`) to the height of your sticky header.
 */
export function FaqSidebarCategories({
  eyebrow,
  title,
  titleAs: Title = "h2",
  description,
  categories,
  contact,
  onCopyLink,
  linkAs: Link = "a",
  labels,
  className,
  ...props
}: FaqSidebarCategoriesProps) {
  const text = { ...LABELS, ...labels };
  const Category = LEVELS[Title].category;
  const Question = LEVELS[Title].question;
  return (
    <section data-slot="faq-sidebar-categories" className={cn("py-16 sm:py-24", className)} {...props}>
      <header className="max-w-2xl">
        {eyebrow ? <p className="mb-4 text-xs font-medium tracking-[.18em] text-muted-foreground uppercase">{eyebrow}</p> : null}
        <Title className="text-3xl font-medium tracking-[-.04em] text-balance sm:text-4xl">{title}</Title>
        {description ? <p className="mt-4 text-base leading-relaxed text-pretty text-muted-foreground">{description}</p> : null}
      </header>
      <div className="mt-10 grid grid-cols-[minmax(0,1fr)] gap-x-16 gap-y-10 lg:mt-14 lg:grid-cols-[13rem_minmax(0,1fr)]">
        <CategoryNav items={categories.map((category) => ({ id: category.id, title: category.title, count: category.questions.length }))} label={text.categories} countLabel={text.questions} />
        <div className="min-w-0">
          {categories.map((category) => (
            <section key={category.id} id={category.id} aria-labelledby={`${category.id}-title`} className="scroll-mt-[calc(var(--sticky-top,5rem)_+_1.5rem)] pb-14 last:pb-0">
              <Category id={`${category.id}-title`} className="text-2xl font-semibold tracking-[-.03em] text-balance">
                {category.title}
              </Category>
              <div className="relative isolate mt-6 divide-y divide-border border-y border-border">
                {category.questions.map((question) => (
                  <div
                    key={question.id}
                    id={question.id}
                    className="group/question relative scroll-mt-[calc(var(--sticky-top,5rem)_+_1.5rem)] py-7 before:absolute before:inset-y-0 before:-inset-x-3 before:-z-10 before:rounded-xl before:bg-muted/70 before:opacity-0 before:transition-opacity before:duration-500 target:before:opacity-100 motion-reduce:before:transition-none"
                  >
                    <div className="flex items-start gap-1">
                      <Question className="min-w-0 text-lg leading-snug font-semibold tracking-[-.02em] text-balance">{question.question}</Question>
                      <CopyLinkButton
                        id={question.id}
                        label={text.copyLink}
                        copiedLabel={text.linkCopied}
                        failedLabel={text.copyFailed}
                        onCopy={onCopyLink}
                        className="-mt-1 transition-[opacity,background-color,color] duration-150 motion-reduce:transition-none [@media(hover:hover)]:opacity-0 [@media(hover:hover)]:group-focus-within/question:opacity-100 [@media(hover:hover)]:group-hover/question:opacity-100 focus-visible:opacity-100"
                      />
                    </div>
                    <div className="mt-3 max-w-2xl text-base leading-relaxed text-muted-foreground [&_a]:font-medium [&_a]:text-foreground [&_a]:underline [&_a]:underline-offset-4 [&_p+p]:mt-3">{question.answer}</div>
                  </div>
                ))}
              </div>
            </section>
          ))}
          {contact ? (
            <aside aria-label={contact.title} className="mt-14 flex flex-wrap items-center justify-between gap-x-8 gap-y-5 rounded-2xl bg-muted/60 p-6 sm:p-8">
              <div className="max-w-md">
                <p className="text-lg font-semibold tracking-[-.02em]">{contact.title}</p>
                {contact.description ? <p className="mt-1.5 text-sm leading-relaxed text-muted-foreground">{contact.description}</p> : null}
              </div>
              <Button asChild variant="outline" size="lg" className="bg-background">
                <Link href={contact.href}>
                  {contact.label}
                  <IconArrowRight />
                </Link>
              </Button>
            </aside>
          ) : null}
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

export interface CategoryNavItem {
  /** The id of the category's section on the page. */
  id: string;
  title: string;
  /** How many questions it holds. */
  count: number;
}

export interface CategoryNavProps {
  items: readonly CategoryNavItem[];
  /** The landmark name. */
  label?: string;
  /** Read after each count: "questions". */
  countLabel?: string;
  className?: string;
}

/**
 * The category list of an FAQ with question counts. The category you are in
 * follows the scroll and carries aria-current, like the table of contents.
 * From lg up it is a vertical list on a rule that sticks beside the answers;
 * below that it is a row of pills that scrolls sideways and keeps the current
 * one in view.
 */
export function CategoryNav({ items, label = "Categories", countLabel = "questions", className }: CategoryNavProps) {
  const [active, setActive] = useState(items[0]?.id ?? "");
  const list = useRef<HTMLOListElement>(null);
  const ids = items.map((item) => item.id).join("\n");

  useEffect(() => {
    const known = ids.split("\n");
    let frame = 0;
    const measure = () => {
      frame = 0;
      const sections = known.map((id) => document.getElementById(id)).filter((node): node is HTMLElement => Boolean(node));
      const first = sections[0];
      if (!first) return;
      const line = window.innerHeight * 0.3;
      let current = first.id;
      for (const section of sections) if (section.getBoundingClientRect().top <= line) current = section.id;
      const last = sections[sections.length - 1];
      if (last && window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) current = last.id;
      setActive(current);
    };
    const schedule = () => {
      if (!frame) frame = window.requestAnimationFrame(measure);
    };
    measure();
    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [ids]);

  useEffect(() => {
    const row = list.current;
    const current = row?.querySelector<HTMLElement>('[aria-current="location"]');
    if (!row || !current || row.scrollWidth <= row.clientWidth) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    row.scrollTo({ left: current.offsetLeft - (row.clientWidth - current.offsetWidth) / 2, behavior: reduced ? "auto" : "smooth" });
  }, [active]);

  return (
    <nav data-slot="faq-category-nav" aria-label={label} className={cn("min-w-0 lg:sticky lg:top-[var(--sticky-top,6rem)] lg:self-start", className)}>
      <p aria-hidden="true" className="mb-3 hidden text-xs font-medium tracking-[.14em] text-muted-foreground uppercase lg:block">
        {label}
      </p>
      <ol
        ref={list}
        role="list"
        className="relative -m-1 flex gap-2 overflow-x-auto p-1 [scrollbar-width:none] lg:m-0 lg:flex-col lg:gap-0 lg:overflow-visible lg:border-l lg:border-border lg:p-0 [&::-webkit-scrollbar]:hidden"
      >
        {items.map((item) => (
          <li key={item.id} className="shrink-0">
            <a
              href={`#${item.id}`}
              aria-current={item.id === active ? "location" : undefined}
              onClick={() => setActive(item.id)}
              className={cn(
                "flex items-center text-sm whitespace-nowrap outline-none transition-colors duration-150 motion-reduce:transition-none focus-visible:ring-[3px] focus-visible:ring-ring/40",
                "max-lg:gap-2 max-lg:rounded-full max-lg:border max-lg:border-border max-lg:px-3.5 max-lg:py-1.5 max-lg:text-muted-foreground max-lg:hover:border-foreground/30 max-lg:hover:text-foreground max-lg:aria-[current=location]:border-foreground max-lg:aria-[current=location]:bg-foreground max-lg:aria-[current=location]:text-background",
                "lg:-ml-px lg:justify-between lg:gap-4 lg:border-l-2 lg:border-transparent lg:py-1.5 lg:pr-2 lg:pl-4 lg:text-muted-foreground lg:hover:text-foreground lg:aria-[current=location]:border-foreground lg:aria-[current=location]:font-medium lg:aria-[current=location]:text-foreground",
              )}
            >
              {item.title}
              <span aria-hidden="true" className="text-xs tabular-nums opacity-80 lg:opacity-100">
                {item.count}
              </span>
              <span className="sr-only">
                {" "}
                ({item.count} {countLabel})
              </span>
            </a>
          </li>
        ))}
      </ol>
    </nav>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { IconCheck, IconLink } from "@rhs-ui/icons";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export interface CopyLinkButtonProps {
  /** The id of the answer: the link is this page's address with #id. */
  id: string;
  /** The button's accessible name. */
  label?: string;
  /** Said in words after the copy worked. */
  copiedLabel?: string;
  /** Said when the browser refused to copy; the address bar already holds the link. */
  failedLabel?: string;
  /** Called after the link was copied, with the id and the full address. */
  onCopy?: (id: string, url: string) => void;
  className?: string;
}

/**
 * The permalink button of an answer. It puts #id in the address bar, copies
 * the full link, and confirms in words ("Link copied") in a live region that
 * is also read out. The region is in the page from the start, empty and
 * invisible, and only its text changes, which is what makes a screen reader
 * announce it. The hash is replaced rather than pushed, so the page does not
 * jump and Back still leaves it.
 */
export function CopyLinkButton({ id, label = "Copy link to this answer", copiedLabel = "Link copied", failedLabel = "Copy it from the address bar", onCopy, className }: CopyLinkButtonProps) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);

  const copy = async () => {
    const url = new URL(window.location.href);
    url.hash = id;
    try {
      window.history.replaceState(null, "", url);
    } catch {
      // A sandboxed frame may refuse to rewrite its address; the link is still copied.
    }
    let next: "copied" | "failed" = "copied";
    try {
      await navigator.clipboard.writeText(url.href);
    } catch {
      next = "failed";
    }
    setState(next);
    if (next === "copied") onCopy?.(id, url.href);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setState("idle"), 2400);
  };

  return (
    <span data-slot="copy-link-button" className="relative flex shrink-0">
      <span role="status" className="pointer-events-none absolute right-0 bottom-full z-10 mb-1.5 rounded-md bg-foreground px-2.5 py-1 text-xs font-medium whitespace-nowrap text-background shadow-sm empty:opacity-0">
        {state === "copied" ? copiedLabel : state === "failed" ? failedLabel : ""}
      </span>
      <Button type="button" variant="ghost" size="icon-sm" aria-label={label} title={label} onClick={() => void copy()} className={cn("text-muted-foreground hover:text-foreground", className)}>
        {state === "copied" ? <IconCheck /> : <IconLink />}
      </Button>
    </span>
  );
}
